<script setup lang="ts">import{ref,onMounted,computed}from'vue';import{http}from'@/shared/api/httpClient';const ventas=ref<any[]>([]),caja=ref(0),pendientes=ref<any[]>([]);onMounted(async()=>{const[v,c,p]=await Promise.allSettled([http.get('/ventas?pageSize=5'),http.get('/caja'),http.get('/cuotas/pendientes')]);if(v.status==='fulfilled')ventas.value=v.value.data.items;if(c.status==='fulfilled')caja.value=c.value.data.saldo;if(p.status==='fulfilled')pendientes.value=p.value.data});const facturado=computed(()=>ventas.value.reduce((a,v)=>a+v.precioTotal,0));const money=(v:number)=>v.toLocaleString('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0});</script>
<template><section class="page"><div class="page-title"><div><h2>Hola, bienvenido</h2><p>Una vista rápida de tu operación comercial.</p></div><RouterLink class="btn" to="/ventas">+ Nueva venta</RouterLink></div><div class="grid"><article class="card metric"><small>Facturación reciente</small><strong>{{money(facturado)}}</strong><em>{{ventas.length}} operaciones</em></article><article class="card metric"><small>Saldo en caja</small><strong>{{money(caja)}}</strong><em>Saldo calculado en tiempo real</em></article><article class="card metric"><small>Cuotas pendientes</small><strong>{{pendientes.length}}</strong><em>Requieren seguimiento</em></article><article class="card metric"><small>Metros vendidos</small><strong>{{ventas.reduce((a,v)=>a+v.cantidadM2,0)}} m²</strong><em>Ventas recientes</em></article></div><div class="panel"><div class="panel-head"><h3>Últimas ventas</h3><RouterLink to="/ventas">Ver todas</RouterLink></div><table><thead><tr><th>Cliente</th><th>Producto</th><th>Fecha</th><th>Total</th><th>Estado</th></tr></thead><tbody><tr v-for="v in ventas" :key="v.id"><td><b>{{v.cliente}}</b></td><td>{{v.tipoCesped}}</td><td>{{v.fechaVenta}}</td><td>{{money(v.precioTotal)}}</td><td><span class="badge">{{v.estado}}</span></td></tr></tbody></table><div v-if="!ventas.length" class="empty">Todavía no hay ventas registradas.</div></div></section></template>
